25283	    op = str(node.attrs.get("op", "sum"))
25284	    fn_name = f"synth_reduce_{_synth_sanitize(node.name)}"
25285	    n_elems = 1
25286	    for s in shape:
25287	        n_elems *= int(s)
25288	    init_v = "0" if op == "sum" else ("-INFINITY" if op == "max" else "1")
25289	    combine = {
25290	        "sum":  "acc + v",
25291	        "max":  "fmaxf(acc, v)",
25292	        "prod": "acc * v",
25293	    }.get(op, "acc + v")
