25295	    use_warp_fast = (n_elems <= _REDUCE_WARP_FAST_THRESHOLD)
25296	    inp = node.inputs[0] if node.inputs else "x"
25297	    # Cross-block combine for the large-tensor path. atomicAdd is only
25298	    # correct for sum; max/prod need an op-matching atomic or they would
25299	    # return the SUM of per-block maxima/products. Emit CAS-based helpers
25300	    # for max/prod (typed to accum_t). The output buffer must be
25301	    # pre-initialised to the op identity by the caller (the standard
25302	    # contract for atomic reductions; true for atomicAdd's zero too).
25303	    _is_double = (accum_t == "double")
25304	    if op == "max":
25305	        _atomic_call = f"_synth_atomic_max_{accum_t}({node.output}_ptr, acc)"
25306	    elif op == "prod":
25307	        _atomic_call = f"_synth_atomic_mul_{accum_t}({node.output}_ptr, acc)"
25308	    else:
25309	        _atomic_call = f"atomicAdd({node.output}_ptr, ({scalar_t})acc)"
25310	    if op in ("max", "prod") and use_warp_fast is False:
25311	        _bits_t = "unsigned long long int" if _is_double else "int"
25312	        _as_bits = "__double_as_longlong" if _is_double else "__float_as_int"
25313	        _from_bits = "__longlong_as_double" if _is_double else "__int_as_float"
25314	        _fmax = "fmax" if _is_double else "fmaxf"
25315	        _op_expr = (f"{_fmax}(cur, val)" if op == "max" else "cur * val")
25316	        _helper_name = (f"_synth_atomic_max_{accum_t}" if op == "max"
25317	                        else f"_synth_atomic_mul_{accum_t}")
25318	        _atomic_helper = f"""
25319	__device__ {accum_t} {_helper_name}({accum_t}* addr, {accum_t} val) {{
25320	    {_bits_t}* a = ({_bits_t}*)addr;
25321	    {_bits_t} old = *a, assumed;
25322	    do {{
25323	        assumed = old;
25324	        {accum_t} cur = {_from_bits}(assumed);
25325	        old = atomicCAS(a, assumed, {_as_bits}({_op_expr}));
25326	    }} while (assumed != old);
25327	    return {_from_bits}(old);
25328	}}
25329	"""
25330	    else:
25331	        _atomic_helper = ""
25332	    if use_warp_fast:
25333	        body = f"""
25334	    // small tensor — single warp shuffle reduce
25335	    {accum_t} acc = ({accum_t}){init_v};
25336	    for (int i = threadIdx.x; i < n; i += blockDim.x) {{
25337	        {accum_t} v = ({accum_t}){inp}_ptr[i];
25338	        acc = {combine};
25339	    }}
25340	    for (int off = warpSize / 2; off > 0; off >>= 1) {{
25341	        {accum_t} v = __shfl_down_sync(0xffffffffu, acc, off);
25342	        acc = {combine};
25343	    }}
25344	    if (threadIdx.x == 0) {{ *{node.output}_ptr = ({scalar_t})acc; }}
25345	""".rstrip("\n")
25346	    else:
25347	        body = f"""
25348	    // large tensor — block reduce + atomic
25349	    __shared__ {accum_t} smem[32];
25350	    {accum_t} acc = ({accum_t}){init_v};
25351	    const int gid = blockIdx.x * blockDim.x + threadIdx.x;
25352	    const int stride = blockDim.x * gridDim.x;
25353	    for (int i = gid; i < n; i += stride) {{
25354	        {accum_t} v = ({accum_t}){inp}_ptr[i];
25355	        acc = {combine};
25356	    }}
25357	    // warp-level shuffle inside the block first
25358	    for (int off = warpSize / 2; off > 0; off >>= 1) {{
25359	        {accum_t} v = __shfl_down_sync(0xffffffffu, acc, off);
25360	        acc = {combine};
25361	    }}
