25368	            ? smem[lane] : ({accum_t}){init_v};
25369	        for (int off = warpSize / 2; off > 0; off >>= 1) {{
25370	            {accum_t} v = __shfl_down_sync(0xffffffffu, acc, off);
25371	            acc = {combine};
