25379	        const {scalar_t}* __restrict__ {inp}_ptr,
25380	        {scalar_t}* __restrict__ {node.output}_ptr,
25381	        int n) {{
25382	{body}
25383	}}
25384	""".rstrip("\n") + "\n"
