25650	    """Blelloch parallel scan (work-efficient, in-place on shared mem)."""
25651	    scalar_t, _, _ = _synth_dtype_triple(dtype)
25652	    op = str(node.attrs.get("op", "sum"))
25653	    fn_name = f"synth_scan_{_synth_sanitize(node.name)}"
25654	    combine = "+" if op == "sum" else "?"  # max-scan needs an op fn
25655	    if op == "max":
25656	        # Use a function-style combine so we don't bake "?" into source.
25657	        combine_expr = "fmaxf(a, b)"
25658	    else:
25659	        combine_expr = "a + b"
25660	    inp = node.inputs[0] if node.inputs else "x"
25661	    return f"""
25662	// node: {node.name} (scan, op={op}, Blelloch)
25663	__global__ void {fn_name}(
25664	        const {scalar_t}* __restrict__ {inp}_ptr,
25665	        {scalar_t}* __restrict__ {node.output}_ptr,
25666	        int n) {{
25667	    extern __shared__ {scalar_t} sdata[];
25668	    int tid = threadIdx.x;
25669	    if (tid < n) sdata[tid] = {inp}_ptr[tid];
25670	    __syncthreads();
25671	    // Up-sweep
25672	    for (int d = 1; d < n; d *= 2) {{
25673	        int idx = (tid + 1) * d * 2 - 1;
25674	        if (idx < n) {{
25675	            {scalar_t} a = sdata[idx - d];
25676	            {scalar_t} b = sdata[idx];
25677	            sdata[idx] = ({combine_expr});
25678	        }}
25679	        __syncthreads();
25680	    }}
25681	    // Down-sweep
25682	    if (tid == 0) sdata[n - 1] = 0;
25683	    __syncthreads();
25684	    for (int d = n / 2; d >= 1; d /= 2) {{
25685	        int idx = (tid + 1) * d * 2 - 1;
25686	        if (idx < n) {{
25687	            {scalar_t} a = sdata[idx - d];
25688	            {scalar_t} b = sdata[idx];
25689	            sdata[idx - d] = b;
25690	            sdata[idx] = ({combine_expr});
25691	        }}
25692	        __syncthreads();
25693	    }}
25694	    if (tid < n) {node.output}_ptr[tid] = sdata[tid];
25695	}}
25696	""".rstrip("\n") + "\n"
